sn_aia_tool.script:
(function(inputs) {
    var T = 'x_snc_ptag_engage_engagement_request';
    var gr = new GlideRecord(T);
    if (!inputs || !inputs.request_sys_id || !gr.get(inputs.request_sys_id)) {
        return JSON.stringify({error: 'record not found: ' + (inputs && inputs.request_sys_id)});
    }
    function plain(v, max) {
        var t = ('' + (v || '')).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ')
            .replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim();
        return t.length > max ? t.substring(0, max) + '...' : t;
    }
    var SIGNALS = [['executive_sponsor', 'Executive sponsor'], ['business_owner', 'Business owner'],
                   ['budget', 'Budget'], ['pipeline', 'Pipeline'],
                   ['corporate_alignment', 'Corporate alignment'],
                   ['certified_resources', 'Certified resources'], ['has_customers', 'Existing customers']];
    var signalsFalse = [];
    for (var i = 0; i < SIGNALS.length; i++) {
        if (gr.getValue(SIGNALS[i][0]) !== '1') signalsFalse.push(SIGNALS[i][1]);
    }
    var NARR = [['idea_description', 'Engagement description'],
                ['customer_pain_points', 'Customer pain points'],
                ['value_prop', 'Value proposition'],
                ['what_is_the_partners_ai_strategy', 'Partner AI strategy']];
    var narratives = {};
    for (var j = 0; j < NARR.length; j++) {
        var txt = plain(gr.getValue(NARR[j][0]), 400);
        narratives[NARR[j][1]] = {chars: txt.length, head: txt || '(empty)'};
    }
    var out = {
        number: gr.getValue('number'),
        short_description: gr.getValue('short_description') || '(empty)',
        state: gr.getDisplayValue('state'),
        requester_first_name: ('' + gr.opened_by.first_name) || 'there',
        partner: gr.getDisplayValue('partner') || '(empty)',
        practice: gr.getDisplayValue('practice') || '(empty)',
        tam_missing: !gr.getValue('tam'),
        signals_not_confirmed: signalsFalse,
        narratives: narratives
    };
    return JSON.stringify(out);
})(inputs);
